import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Test.'});
const session = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'test', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> { return {} as T; }
  };
};

const registry = (): ToolRegistry => {
  const r = new ToolRegistry();
  r.register({name: 'lookup', description: 'x', inputSchema: {type: 'object'}}, async () => 'found');
  return r;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {}}};
const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

describe('ChatOrchestrator usage aggregation (unit)', () => {
  it('sums usage across multiple tool rounds', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 5, totalTokens: 15})],
        [{type: 'text', text: 'done'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 10, totalTokens: 30})],
      ]),
      promptBuilder,
      registry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    // Currently it would be {inputTokens: 20, outputTokens: 10, totalTokens: 30}
    expect(reported).toEqual({inputTokens: 30, outputTokens: 15, totalTokens: 45});
  });
});

